MODELS = "memory/topics/firefly-models.md"
GD = "memory/agents/graphic-design.md"
BIG = LOG + "Joust opener/prompt and notes for all the rest this was very time consuming.txt"

ALL = ("video", "still", "edit")


def _r(id, name, sev, tag, kinds, applies, evidence, status, sources, quotes, why, fix, standard_ref="", emitted=True):
    return dict(id=id, name=name, severity=sev, tag=tag, kinds=kinds, applies=applies, evidence=evidence,
                evidence_status=status, sources=sources, quotes=quotes, why=why, fix=fix,
                standard_ref=standard_ref, emitted=emitted)


